239	/**
240	 * Reads requests from the quickapp process via POSIX mqueue and feeds
241	 * them into the local message_bus inbound queue.
242	 */
243	static void *quickapp_mq_listener_task(void *arg)
244	{
245	    (void)arg;
246	    syslog(LOG_INFO, "[%s] Quickapp mqueue listener started\n", TAG);
247	
248	    struct mq_attr attr = {
249	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
250	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
251	    };
252	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
253	    if (mq == (mqd_t)-1) {
254	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
255	        return NULL;
256	    }
257	
258	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
259	    if (!buf) {
260	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
261	        mq_close(mq);
262	        return NULL;
263	    }
264	
265	    while (1) {
266	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
267	        if (n < 0) {
268	            if (errno == EINTR) continue;
269	            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
270	            break;
271	        }
272	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
273	            n = VELACLAW_MQ_MSG_SIZE - 1;
274	        }
275	        buf[n] = '\0';
276	
277	        /* Message format: "chat_id\nquery" */
278	        char *sep = strchr(buf, '\n');
279	        if (!sep) {
280	            syslog(LOG_WARNING, "[%s] Malformed quickapp message\n", TAG);
281	            continue;
282	        }
283	        *sep = '\0';
284	        const char *chat_id = buf;
285	        const char *query = sep + 1;
286	
287	        syslog(LOG_INFO, "[%s] Quickapp request: chat_id=%s query=%.40s\n",
288	               TAG, chat_id, query);
289	
290	        agent_msg_t msg = {0};
291	        strncpy(msg.channel, AGENT_CHAN_QUICKAPP, sizeof(msg.channel) - 1);
292	        strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
293	        msg.content = strdup(query);
294	        if (msg.content) {
295	            message_bus_push_inbound(&msg);
296	        }
297	    }
298	
299	    free(buf);
300	    mq_close(mq);
301	    return NULL;
302	}
