304	/**
305	 * Send a reply to the quickapp process via the outbound mqueue.
306	 * Called from the outbound dispatch thread in the agent process.
307	 */
308	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
309	{
310	    struct mq_attr attr = {
311	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
312	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
313	    };
314	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
315	    if (mq == (mqd_t)-1) {
316	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
317	        return;
318	    }
319	
320	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
321	    if (!buf) {
322	        mq_close(mq);
323	        return;
324	    }
325	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
326	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
327	        len = VELACLAW_MQ_MSG_SIZE - 1;
328	        buf[len] = '\0';
329	    }
330	
331	    if (mq_send(mq, buf, len + 1, 0) != 0) {
332	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
333	    } else {
334	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
335	    }
336	    free(buf);
337	    mq_close(mq);
338	}
