/****************************************************************************
 * Name: nxrecorder
 *
 *   nxrecorder() reads in commands from the console using the readline
 *   system add-in and implements a command-line based pcm raw data recorder
 *   that uses the NuttX audio system to record pcm raw data files read in
 *   from the audio device.  Commands are provided for setting volume, base
 *   and other audio features, as well as for pausing and stopping the
 *   record.
 *
 * Input Parameters:
 *   buf       - The user allocated buffer to be filled.
 *   buflen    - the size of the buffer.
 *   instream  - The stream to read characters from
 *   outstream - The stream to each characters to.
 *
 * Returned values:
 *   On success, the (positive) number of bytes transferred is returned.
 *   EOF is returned to indicate either an end of file condition or a
 *   failure.
 *
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR char               *buffer;
  int                     len;
  int                     x;
  int                     running;
  char                    *cmd;
  char                    *arg;
  FAR struct nxrecorder_s *precorder;

  printf("NxRecorder version " NXRECORDER_VER "\n");
  printf("h for commands, q to exit\n");
  printf("\n");

  /* Initialize our NxRecorder context */

  precorder = nxrecorder_create();
  if (precorder == NULL)
    {
      printf("Error:  Out of RAM\n");
      return -ENOMEM;
    }

  buffer = lib_get_tempbuffer(LINE_MAX);
  if (buffer == NULL)
    {
      nxrecorder_release(precorder);
      printf("Error: lib_get_tempbuffer failed\n");
      return -ENOMEM;
    }

  /* Loop until the user exits */

  running = TRUE;
  while (running)
    {
      /* Print a prompt */

      printf("nxrecorder> ");
      fflush(stdout);

      /* Read a line from the terminal */

      len = readline_stream(buffer, LINE_MAX,
                            stdin, stdout);
      if (len > 0)
        {
          buffer[len] = '\0';
          if (strncmp(buffer, "!", 1) != 0)
            {
              /* nxrecorder command */

              if (buffer[len - 1] == '\n')
                {
                  buffer[len - 1] = '\0';
                }

              /* Parse the command from the argument */

              cmd = strtok_r(buffer, " \n", &arg);
              if (cmd == NULL)
                {
                  continue;
                }

              /* Remove leading spaces from arg */

              while (*arg == ' ')
                {
                  arg++;
                }

              /* Find the command in our cmd array */

              for (x = 0; x < g_nxrecorder_cmd_count; x++)
                {
                  if (strcmp(cmd, g_nxrecorder_cmds[x].cmd) == 0)
                    {
                      /* Command found.  Call it's handler if not NULL */

                      if (g_nxrecorder_cmds[x].pfunc != NULL)
                        {
                          g_nxrecorder_cmds[x].pfunc(precorder, arg);
                        }

                      /* Test if it is a quit command */

                      if (g_nxrecorder_cmds[x].pfunc == nxrecorder_cmd_quit)
                        {
                          running = FALSE;
                        }

 * Name: virtio_snd_getcaps
 ****************************************************************************/

static int virtio_snd_getcaps(FAR struct audio_lowerhalf_s *dev,
                              int type,
                              FAR struct audio_caps_s *caps)
{
  FAR struct virtio_snd_dev_s *sdev = (FAR struct virtio_snd_dev_s *)dev;
  FAR struct virtio_snd_s *priv = sdev->priv;
  FAR struct virtio_snd_pcm_info *info = &priv->info[sdev->index];

  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));

  caps->ac_format.hw  = 0;
  caps->ac_controls.w = 0;

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_QUERY:
        switch (caps->ac_subtype)
          {
            case AUDIO_TYPE_QUERY:
              caps->ac_controls.b[0] =
              info->direction == VIRTIO_SND_D_INPUT ?
                                 AUDIO_TYPE_INPUT : AUDIO_TYPE_OUTPUT;
              caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
              break;

            case AUDIO_FMT_PCM:
              virtio_snd_get_support_formats(info, caps);
              break;

            default:
              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
              break;
          }
         break;

      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          caps->ac_channels = (info->channels_min << 4) |
                              (info->channels_max & 0x0f);
          switch (caps->ac_subtype)
            {
              case AUDIO_TYPE_QUERY:
                caps->ac_controls.b[0] = virtio_snd_get_support_rates(info);
                break;

              default:
                break;
            }
          break;
        }

      default:
        caps->ac_subtype = 0;
        caps->ac_channels = 0;
        break;
    }

  return caps->ac_len;
}

/****************************************************************************
 * Name: virtio_snd_configure
 *
 * Description:
 *   Configure the audio device for the specified  mode of operation.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int virtio_snd_configure(FAR struct audio_lowerhalf_s *dev,
                                FAR void *session,
                                FAR const struct audio_caps_s *caps)
#else
static int virtio_snd_configure(FAR struct audio_lowerhalf_s *dev,
                                FAR const struct audio_caps_s *caps)
#endif
{
  FAR struct virtio_snd_dev_s *sdev = (FAR struct virtio_snd_dev_s *)dev;
  FAR struct virtio_snd_s *priv = sdev->priv;
  FAR struct virtio_snd_pcm_info *info = &priv->info[sdev->index];
  int idx = info->direction == VIRTIO_SND_D_INPUT ?
                               VIRTIO_SND_VQ_RX : VIRTIO_SND_VQ_TX;
  FAR struct virtqueue *vq = priv->vdev->vrings_info[idx].vq;
  int ret = -ENOTTY;
  uint32_t rate;
  uint8_t bps;
  uint8_t ch;

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        vrtinfo("Number of channels: %"PRIu8"\n", caps->ac_channels);
        vrtinfo("Sample rate:        %"PRIu16"\n", caps->ac_controls.hw[0]);
        vrtinfo("Sample width:       %"PRIu8"\n", caps->ac_controls.b[2]);
        vrtinfo("channel map: 0x%x\n", caps->ac_chmap);
        rate = caps->ac_controls.hw[0] | (caps->ac_controls.b[3] << 16);
        bps = caps->ac_controls.b[2];
        ch = caps->ac_channels;
        sdev->frame_size = ch * bps / 8;
        sdev->period_count = MIN(CONFIG_DRIVERS_VIRTIO_SND_BUFFER_COUNT,
                                 vq->vq_nentries / 2);
        sdev->period_bytes =
        virtio_snd_get_period_bytes(rate, ch, bps,
                                    CONFIG_DRIVERS_VIRTIO_SOUND_PERIOD_TIME *
                                    CONFIG_DRIVERS_VIRTIO_SND_BUFFER_COUNT /
                                    sdev->period_count);
        vrtinfo("period_bytes:%"PRIu32"\n", sdev->period_bytes);
        ret = virtio_snd_set_params(sdev, ch, rate, bps);
        if (ret < 0)
          {
            break;
          }

        ret = virtio_snd_send_cmd(sdev, VIRTIO_SND_R_PCM_PREPARE);
        break;
    }

  return ret;
}

