int audio_capture_start(audio_capture_t* cap)
{
    if (!cap) {
        return -EINVAL;
    }

    switch (cap->backend) {
    case AUDIO_CAPTURE_BACKEND_NUTTX:
#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
        if (cap->handle.fd < 0) {
            return -EINVAL;
        }

        if (cap->started) {
            return 0;
        }

        if (ioctl(cap->handle.fd, AUDIOIOC_START, 0) < 0) {
            syslog(LOG_ERR, "[%s] AUDIOIOC_START failed: %d\n",
                TAG, errno);
            return -errno;
        }

        cap->started = 1;
        syslog(LOG_INFO, "[%s] NuttX audio capture started\n", TAG);
        return 0;
#else
        return -ENOTSUP;
#endif

    case AUDIO_CAPTURE_BACKEND_ALSA:
#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
        if (!cap->handle.pcm) {
            return -EINVAL;
        }

        if (cap->started) {
            return 0;
        }

        if (snd_vela_pcm_prepare(cap->handle.pcm) < 0) {
            syslog(LOG_ERR, "[%s] ALSA prepare failed\n", TAG);
            return -EIO;
        }

        cap->started = 1;
        syslog(LOG_INFO, "[%s] ALSA capture prepared\n", TAG);
        return 0;
#else
        return -ENOTSUP;
#endif

    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
        int ret;

        if (!cap->handle.recorder) {
            return -EINVAL;
        }

        ret = media_recorder_start(cap->handle.recorder);
        if (ret < 0) {
            syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
            return ret;
        }

        syslog(LOG_INFO, "[%s] media recorder capture started\n", TAG);
        return 0;
    }

    default:
        return -EINVAL;
    }
}

