815	        s_token, sizeof(s_token));
816	
817	    if (claw_config_get(AGENT_CFG_KEY_VOLC_ASR_CLUSTER,
818	            s_cluster, sizeof(s_cluster))
819	            != OK
820	        || s_cluster[0] == '\0') {
821	        strncpy(s_cluster, AGENT_DOUBAO_ASR_CLUSTER,
822	            sizeof(s_cluster) - 1);
823	    }
