#!/usr/bin/env python3
"""Persistent single-connection driver for the goldfish shell-serial console.
Boot-wait -> ai_agent -> run each argv command, waiting for the vela> prompt."""
import socket, time, select, sys

HOST = "127.0.0.1"
PORT = 5560

def main():
    s = socket.create_connection((HOST, PORT), timeout=5)
    s.setblocking(False)

    def read_until(markers, timeout):
        end = time.time() + timeout
        buf = b""
        while time.time() < end:
            r, _, _ = select.select([s], [], [], 0.1)
            if r:
                try:
                    d = s.recv(65536)
                    if not d:
                        return buf, None
                    buf += d
                    for m in markers:
                        if m in buf:
                            return buf, m
                except BlockingIOError:
                    pass
        return buf, None

    def emit(buf):
        if buf:
            sys.stdout.buffer.write(buf)
            sys.stdout.buffer.flush()

    # Phase 1: wait for NSH prompt (boot may still be in progress)
    buf, m = read_until([b"goldfish-armv8a-ap>"], 90)
    emit(buf)
    if m is None:
        print("\n[driver] TIMEOUT waiting for NSH prompt", file=sys.stderr)
        s.close(); return

    # Phase 2: enter ai_agent
    s.sendall(b"ai_agent\n")
    buf, m = read_until([b"vela>"], 20)
    emit(buf)
    if m is None:
        print("\n[driver] TIMEOUT waiting for vela> after ai_agent", file=sys.stderr)
        s.close(); return

    # Phase 3: run each command
    cmds = sys.argv[1:]
    for c in cmds:
        s.sendall((c + "\n").encode())
        buf, m = read_until([b"vela>"], 25)
        emit(buf)

    s.close()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Single-connection full flow: boot-wait -> network -> ai_agent -> config_show."""
import socket, time, select, sys

HOST = "127.0.0.1"
PORT = 5560
PROMPT = b"goldfish-armv8a-ap>"

def connect_retry(timeout=120):
    end = time.time() + timeout
    while time.time() < end:
        try:
            s = socket.create_connection((HOST, PORT), timeout=5)
            s.setblocking(False)
            return s
        except OSError:
            time.sleep(1)
    return None

def read_until(s, markers, timeout):
    end = time.time() + timeout
    buf = b""
    while time.time() < end:
        r, _, _ = select.select([s], [], [], 0.1)
        if r:
            try:
                d = s.recv(65536)
                if not d:
                    return buf, None
                buf += d
                for m in markers:
                    if m in buf:
                        return buf, m
            except BlockingIOError:
                pass
    return buf, None

def emit(b):
    if b:
        sys.stdout.buffer.write(b)
        sys.stdout.buffer.flush()

def main():
    s = connect_retry(120)
    if not s:
        print("[driver] connect timeout", file=sys.stderr); return

    # poll for NSH prompt
    got = False
    end = time.time() + 150
    while time.time() < end:
        s.sendall(b"\n")
        buf, m = read_until(s, [PROMPT], 4)
        if m:
            emit(buf)
            got = True
            break
        time.sleep(1)
    if not got:
        print("\n[driver] no NSH prompt in 150s", file=sys.stderr); s.close(); return

    def cmd(c, wait=4):
        s.sendall(c.encode() + b"\n")
        buf, _ = read_until(s, [PROMPT], wait)
        emit(buf)

    # network
    cmd("ifup eth0", 3)
    cmd("renew eth0", 6)

    # enter ai_agent
    s.sendall(b"ai_agent\n")
    buf, m = read_until(s, [b"vela>"], 20)
    emit(buf)
    if not m:
        print("\n[driver] no vela> after ai_agent", file=sys.stderr); s.close(); return

    # config_show (verify persisted credentials)
    s.sendall(b"config_show\n")
    buf, m = read_until(s, [b"vela>"], 15)
    emit(buf)

    s.close()

if __name__ == "__main__":
    main()

