def parse_volc_response(raw):
    # raw = binary frame: [volc 4B hdr][4B payload_size][payload]
    if len(raw) < 8:
        return f"short frame ({len(raw)}B): {raw.hex()}"
    ver = raw[0]; msg_type = raw[1]; ser = raw[2]
    plen = struct.unpack(">I", raw[4:8])[0]
    payload = raw[8:8+plen]
    try:
        return f"msg_type=0x{msg_type:02x} ser=0x{ser:02x} plen={plen} payload={payload.decode('utf-8','replace')}"
