242	            got += (size_t)ret;
243	        } else if (ret == 0
244	            || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
245	            return -ECONNRESET;
246	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
247	            syslog(LOG_ERR, "[%s] ssl_read: -0x%04x\n", TAG, -ret);
248	            return -EIO;
249	        }
250	    }
251	    return 0;
252	}
