254	/* ── UUID generation (simple v4-like) ────────────────────────── */
255	
256	static void generate_uuid(char* out, size_t cap)
257	{
258	    unsigned char rnd[16];
259	
260	    asr_entropy_func(NULL, rnd, sizeof(rnd));
261	    rnd[6] = (rnd[6] & 0x0F) | 0x40; /* version 4 */
262	    rnd[8] = (rnd[8] & 0x3F) | 0x80; /* variant 1 */
263	    snprintf(out, cap,
264	        "%02x%02x%02x%02x-%02x%02x-%02x%02x-"
265	        "%02x%02x-%02x%02x%02x%02x%02x%02x",
266	        rnd[0], rnd[1], rnd[2], rnd[3],
267	        rnd[4], rnd[5], rnd[6], rnd[7],
268	        rnd[8], rnd[9], rnd[10], rnd[11],
269	        rnd[12], rnd[13], rnd[14], rnd[15]);
270	}
