272	/* ── WebSocket upgrade handshake ─────────────────────────────── */
273	
274	static int ws_upgrade(asr_tls_ctx_t* ctx, const char* host,
275	    const char* path, const char* token)
276	{
277	    /* Generate random 16-byte key, base64-encode it */
278	    unsigned char key_raw[16];
279	    unsigned char key_b64[32];
280	    size_t key_b64_len;
281	
282	    asr_entropy_func(NULL, key_raw, sizeof(key_raw));
283	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len,
284	        key_raw, sizeof(key_raw));
285	
286	    char req[768];
287	    int n = snprintf(req, sizeof(req),
288	        "GET %s HTTP/1.1\r\n"
289	        "Host: %s\r\n"
290	        "Upgrade: websocket\r\n"
291	        "Connection: Upgrade\r\n"
292	        "Sec-WebSocket-Key: %.*s\r\n"
293	        "Sec-WebSocket-Version: 13\r\n"
294	        "Authorization: Bearer;%s\r\n"
295	        "\r\n",
296	        path, host, (int)key_b64_len, key_b64,
297	        token);
298	
299	    if (n <= 0 || n >= (int)sizeof(req)) {
300	        return -EOVERFLOW;
301	    }
302	
303	    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);
304	
305	    if (ret != 0) {
306	        return ret;
307	    }
308	
309	    /* Read HTTP 101 response */
310	    char resp[WS_BUF_SIZE];
311	    size_t rlen = 0;
312	
313	    while (rlen < sizeof(resp) - 1) {
314	        int r = mbedtls_ssl_read(&ctx->ssl,
315	            (unsigned char*)resp + rlen,
316	            sizeof(resp) - 1 - rlen);
317	
318	        if (r > 0) {
319	            rlen += (size_t)r;
320	            resp[rlen] = '\0';
321	            if (strstr(resp, "\r\n\r\n")) {
322	                break;
323	            }
324	        } else if (r == 0
325	            || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
326	            return -ECONNRESET;
327	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
328	            return -EIO;
329	        }
330	    }
331	
332	    int status = 0;
333	
334	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
335	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n",
336	            TAG, status);
337	        return -EPROTO;
338	    }
339	
340	    syslog(LOG_INFO, "[%s] WebSocket upgrade OK\n", TAG);
341	    return 0;
342	}
