344	/* ── WebSocket frame send (client must mask) ─────────────────── */
345	
346	static int ws_send_binary(asr_tls_ctx_t* ctx,
347	    const unsigned char* payload, size_t plen)
348	{
349	    unsigned char hdr[14]; /* max WS header: 2 + 8 + 4 */
350	    size_t hdr_len = 0;
351	
352	    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;
353	
354	    if (plen < 126) {
355	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
356	        hdr_len = 2;
357	    } else if (plen <= 0xFFFF) {
358	        hdr[1] = WS_MASK_BIT | 126;
359	        hdr[2] = (unsigned char)(plen >> 8);
360	        hdr[3] = (unsigned char)(plen & 0xFF);
361	        hdr_len = 4;
362	    } else {
363	        hdr[1] = WS_MASK_BIT | 127;
364	        memset(hdr + 2, 0, 4); /* high 32 bits = 0 */
365	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
366	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
367	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
368	        hdr[9] = (unsigned char)(plen & 0xFF);
369	        hdr_len = 10;
370	    }
371	
372	    /* Generate 4-byte mask key */
373	    unsigned char mask[WS_MASK_KEY_LEN];
374	
375	    asr_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
376	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
377	    hdr_len += WS_MASK_KEY_LEN;
378	
379	    /* Send header */
380	    int ret = tls_write_all(ctx, hdr, hdr_len);
381	
382	    if (ret != 0) {
383	        return ret;
384	    }
385	
386	    /* Mask and send payload in chunks to avoid large stack alloc */
387	    unsigned char chunk[1024];
388	    size_t sent = 0;
389	
390	    while (sent < plen) {
391	        size_t clen = plen - sent;
392	
393	        if (clen > sizeof(chunk)) {
394	            clen = sizeof(chunk);
395	        }
396	        for (size_t i = 0; i < clen; i++) {
397	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
398	        }
399	        ret = tls_write_all(ctx, chunk, clen);
400	        if (ret != 0) {
401	            return ret;
402	        }
403	        sent += clen;
404	    }
405	
406	    return 0;
407	}
408	
409	/* ── WebSocket frame recv ────────────────────────────────────── */
410	
411	static int ws_recv_frame(asr_tls_ctx_t* ctx,
412	    unsigned char* buf, size_t cap,
413	    size_t* out_len, int* out_opcode)
414	{
415	    unsigned char hdr[2];
416	    int ret = tls_read_all(ctx, hdr, 2);
417	
418	    if (ret != 0) {
419	        return ret;
420	    }
421	
422	    *out_opcode = hdr[0] & 0x0F;
423	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
424	    size_t plen = hdr[1] & 0x7F;
425	
426	    if (plen == 126) {
427	        unsigned char ext[2];
428	
429	        ret = tls_read_all(ctx, ext, 2);
430	        if (ret != 0) {
431	            return ret;
432	        }
433	        plen = ((size_t)ext[0] << 8) | ext[1];
434	    } else if (plen == 127) {
435	        unsigned char ext[8];
436	
437	        ret = tls_read_all(ctx, ext, 8);
438	        if (ret != 0) {
439	            return ret;
440	        }
441	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16)
442	            | ((size_t)ext[6] << 8) | ext[7];
443	    }
444	
445	    unsigned char mask[WS_MASK_KEY_LEN];
446	
447	    if (masked) {
448	        ret = tls_read_all(ctx, mask, WS_MASK_KEY_LEN);
449	        if (ret != 0) {
450	            return ret;
451	        }
452	    }
453	
454	    if (plen > cap) {
455	        syslog(LOG_ERR, "[%s] WS frame too large: %zu > %zu\n",
456	            TAG, plen, cap);
457	        return -EOVERFLOW;
458	    }
459	
460	    if (plen > 0) {
461	        ret = tls_read_all(ctx, buf, plen);
462	        if (ret != 0) {
463	            return ret;
464	        }
465	        if (masked) {
466	            for (size_t i = 0; i < plen; i++) {
467	                buf[i] ^= mask[i % 4];
468	            }
469	        }
470	    }
471	
472	    *out_len = plen;
473	    return 0;
474	}
