476	/* ── Volcengine binary frame builders ────────────────────────── */
477	
478	/* Build a Volcengine header (8 bytes) and wrap payload into a
479	 * standard WebSocket binary frame for sending. */
480	static int send_volc_frame(asr_tls_ctx_t* ctx,
481	    unsigned char msg_type,
482	    unsigned char serialization,
483	    const unsigned char* payload,
484	    size_t plen)
485	{
486	    unsigned char* frame = malloc(VOLC_HDR_SIZE + plen);
487	
488	    if (!frame) {
489	        return -ENOMEM;
490	    }
491	
492	    frame[0] = VOLC_PROTO_VER;
493	    frame[1] = msg_type;
494	    frame[2] = serialization;
495	    frame[3] = 0x00;
496	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
497	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
498	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
499	    frame[7] = (unsigned char)(plen & 0xFF);
500	
501	    if (plen > 0) {
502	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
503	    }
504	
505	    int ret = ws_send_binary(ctx, frame, VOLC_HDR_SIZE + plen);
506	
507	    free(frame);
508	    return ret;
509	}
