511	/* Build and send the full_client_request JSON metadata. */
512	static int send_full_client_request(asr_tls_ctx_t* ctx,
513	    const char* app_id,
514	    const char* token,
515	    const char* cluster)
516	{
517	    char reqid[ASR_UUID_LEN];
518	
519	    generate_uuid(reqid, sizeof(reqid));
520	
521	    cJSON* root = cJSON_CreateObject();
522	
523	    if (!root) {
524	        return -ENOMEM;
525	    }
526	
527	    /* app */
528	    cJSON* app = cJSON_AddObjectToObject(root, "app");
529	
530	    cJSON_AddStringToObject(app, "appid", app_id);
531	    cJSON_AddStringToObject(app, "token", token);
532	    cJSON_AddStringToObject(app, "cluster", cluster);
533	
534	    /* user */
535	    cJSON* user = cJSON_AddObjectToObject(root, "user");
536	
537	    cJSON_AddStringToObject(user, "uid", "agent");
538	
539	    /* audio */
540	    cJSON* audio = cJSON_AddObjectToObject(root, "audio");
541	
542	    cJSON_AddStringToObject(audio, "format", "raw");
543	    cJSON_AddNumberToObject(audio, "rate",
544	        AGENT_VOICE_SAMPLE_RATE);
545	    cJSON_AddNumberToObject(audio, "bits", AGENT_VOICE_BITS);
546	    cJSON_AddNumberToObject(audio, "channel",
547	        AGENT_VOICE_CHANNELS);
548	    cJSON_AddStringToObject(audio, "language", "zh-CN");
549	
550	    /* request */
551	    cJSON* req = cJSON_AddObjectToObject(root, "request");
552	
553	    cJSON_AddStringToObject(req, "reqid", reqid);
554	    cJSON_AddStringToObject(req, "workflow",
555	        "audio_in,resample,partition,vad,fe,decode");
556	    cJSON_AddNumberToObject(req, "sequence", 1);
557	    cJSON_AddNumberToObject(req, "nbest", 1);
558	    cJSON_AddBoolToObject(req, "show_utterances", 0);
559	    /* VAD: avoid cutting short commands on QEMU virtual mic */
560	    cJSON_AddBoolToObject(req, "vad_signal", 1);
561	    cJSON_AddStringToObject(req, "start_silence_time", "3000");
562	    cJSON_AddStringToObject(req, "vad_silence_time", "800");
563	
564	    char* json_str = cJSON_PrintUnformatted(root);
565	
566	    cJSON_Delete(root);
567	
568	    if (!json_str) {
569	        return -ENOMEM;
570	    }
571	
572	    syslog(LOG_INFO, "[%s] full_client_request: reqid=%s\n",
573	        TAG, reqid);
574	
575	    int ret = send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_SER_JSON,
576	        (const unsigned char*)json_str,
577	        strlen(json_str));
578	    free(json_str);
579	    return ret;
580	}
