```c
static int recv_volc_response(asr_tls_ctx_t* ctx,
    char* text_out, size_t text_cap)
{
    unsigned char* buf = malloc(WS_BUF_SIZE);
    ...
    int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
    ...
    if (opcode == WS_OPCODE_CLOSE) { ... return -ECONNRESET; }
    if (flen < 4) { ... return -EPROTO; }

    int hdr_units = buf[0] & 0x0F;
    size_t volc_hdr_len = (size_t)hdr_units * 4;
    unsigned char msg_type_byte = buf[1];
    unsigned char msg_type_nibble = (msg_type_byte >> 4) & 0x0F;
    unsigned char msg_flags = msg_type_byte & 0x0F;

    if (volc_hdr_len < 4 || flen < volc_hdr_len) { ... return -EPROTO; }

    /* Error frame (0xF): [4B hdr][4B err_code][4B err_size][err_text] */
    if (msg_type_nibble == 0x0F) {
        ... (keep existing, it's correct for v3)
        return -EIO;
    }

    /* Normal response: [4B hdr][(optional 4B seq)][4B plen][payload] */
    size_t off = volc_hdr_len;
    if (msg_flags & 0x01) {
        off += 4;  /* sequence present */
    }
    if (flen < off + 4) { ... return -EPROTO; }
    uint32_t payload_len = read_be32(buf, off);
    size_t data_off = off + 4;
    if (data_off + payload_len > flen) { ... return -EPROTO; }

    if (msg_type_nibble != 0x09) {
        free(buf); return 0;  /* skip unknown */
    }

    buf[data_off + payload_len] = '\0';
    cJSON* root = cJSON_Parse((char*)(buf + data_off));
    free(buf); buf = NULL;
    if (!root) { ... return -EPROTO; }

    /* v3: result.text is a string; no code/message wrapper */
    cJSON* result = cJSON_GetObjectItem(root, "result");
    if (cJSON_IsObject(result)) {
        cJSON* txt = cJSON_GetObjectItem(result, "text");
        if (txt && cJSON_IsString(txt) && txt->valuestring) {
            strncpy(text_out, txt->valuestring, text_cap - 1);
            text_out[text_cap - 1] = '\0';
        }
    }
    cJSON_Delete(root);

    /* final when flags has bit 0x2 (last packet) */
    return (msg_flags & 0x02) ? 1 : 0;
}
```

