#!/usr/bin/env python3
"""Reconnect to running guest, re-run voice_test_asr, capture result until marker."""
import socket, time, select

HOST = "127.0.0.1"; PORT = 5560
OUT = "/tmp/vela_asr_result.txt"

def log(m): print(m, flush=True)

def connect_retry(timeout=60):
    end = time.time() + timeout
    while time.time() < end:
        try:
            s = socket.create_connection((HOST, PORT), timeout=5)
            s.setblocking(False)
            return s
        except OSError:
            time.sleep(1)
    return None

def main():
    open(OUT, "wb").close()
    s = connect_retry(60)
    if not s:
        log("connect failed"); return
    log("connected")

    # trigger prompt, confirm ai_agent alive
    buf = b""
    end = time.time() + 20
    while time.time() < end and b"vela>" not in buf:
        s.sendall(b"\n")
        r, _, _ = select.select([s], [], [], 1.0)
        if r:
            try:
                d = s.recv(65536)
            except BlockingIOError:
                d = b""
            if not d:
                break
            buf += d
            with open(OUT, "ab") as f: f.write(d)
    log("prompt ok: %s" % (b"vela>" in buf))

    # run ASR test
    s.sendall(b"voice_test_asr /tmp/speech16k.pcm\n")
    log("ASR test sent")

    # wait for result marker (background thread prints later)
    result = b""
    end = time.time() + 60
    while time.time() < end:
        r, _, _ = select.select([s], [], [], 1.0)
        if r:
            try:
                d = s.recv(65536)
            except BlockingIOError:
                d = b""
            if not d:
                log("serial EOF")
                break
            result += d
            with open(OUT, "ab") as f: f.write(d)
            if b"ASR result" in result or b"ASR failed" in result or b"ASR error" in result:
                break
    log("captured (len=%d)" % len(result))
    log("DONE")

if __name__ == "__main__":
    main()

