#!/usr/bin/env python3
"""Reconnect, run voice_start -> wait -> voice_stop, capture streaming result."""
import socket, time, select

HOST = "127.0.0.1"; PORT = 5560
OUT = "/tmp/vela_stream_result.txt"

def log(m): print(m, flush=True)

def connect_retry(timeout=60):
    end = time.time() + timeout
    while time.time() < end:
        try:
            s = socket.create_connection((HOST, PORT), timeout=5)
            s.setblocking(False)
            return s
        except OSError:
            time.sleep(1)
    return None

def drain(s, out, seconds):
    end = time.time() + seconds
    buf = b""
    while time.time() < end:
        r, _, _ = select.select([s], [], [], 0.2)
        if r:
            try:
                d = s.recv(65536)
            except BlockingIOError:
                d = b""
            if not d:
                return buf, False
            buf += d
            out.write(d)
    return buf, True

def main():
    open(OUT, "wb").close()
    out = open(OUT, "ab", buffering=0)
    s = connect_retry(60)
    if not s:
        log("connect failed"); return
    log("connected")

    # trigger prompt
    buf = b""
    end = time.time() + 20
    while time.time() < end and b"vela>" not in buf:
        s.sendall(b"\n")
        r, _, _ = select.select([s], [], [], 1.0)
        if r:
            try: d = s.recv(65536)
            except BlockingIOError: d = b""
            if not d: break
            buf += d; out.write(d)
    log("prompt ok: %s" % (b"vela>" in buf))

    # voice_start
    s.sendall(b"voice_start\n")
    buf, ok = drain(s, out, 6)
    log("voice_start: ok=%s (got %dB)" % (ok, len(buf)))

    # record ~4s (silence or whatever source)
    time.sleep(4)
    buf, _ = drain(s, out, 1)

    # voice_stop
    s.sendall(b"voice_stop\n")
    log("voice_stop sent, waiting for ASR result...")

    # wait for result / error markers up to 40s
    result = b""
    end = time.time() + 40
    while time.time() < end:
        r, _, _ = select.select([s], [], [], 1.0)
        if r:
            try: d = s.recv(65536)
            except BlockingIOError: d = b""
            if not d:
                log("serial EOF"); break
            result += d; out.write(d)
            if b"ASR result" in result or b"ASR failed" in result or b"voice_started" in result or b"voice stopped" in result:
                pass
        # keep waiting a bit after result to catch injection
        if (b"ASR result" in result or b"ASR failed" in result) and b"vela>" in result:
            break
    log("streaming captured %dB" % len(result))
    log("DONE")

if __name__ == "__main__":
    main()

