617	    }
618	
619	    size_t flen;
620	    int opcode;
621	    int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
622	
623	    if (ret != 0) {
624	        free(buf);
625	        return ret;
626	    }
627	
628	    if (opcode == WS_OPCODE_CLOSE) {
629	        syslog(LOG_WARNING, "[%s] Server sent WS close\n", TAG);
630	        free(buf);
631	        return -ECONNRESET;
632	    }
633	
634	    /* Need at least Volcengine header (4 bytes minimum) */
635	    if (flen < 4) {
636	        syslog(LOG_ERR, "[%s] Frame too short: %zu\n", TAG, flen);
637	        free(buf);
638	        return -EPROTO;
639	    }
640	
641	    /* Parse Volcengine header */
642	    int hdr_units = buf[0] & 0x0F;
643	    size_t volc_hdr_len = (size_t)hdr_units * 4;
644	    unsigned char msg_type_byte = buf[1];
645	    unsigned char msg_type_nibble = (msg_type_byte >> 4) & 0x0F;
646	    unsigned char msg_flags = msg_type_byte & 0x0F;
647	
648	    if (volc_hdr_len < 4 || flen < volc_hdr_len) {
649	        syslog(LOG_ERR,
