850	
851	    /* 1. TLS connect */
852	    ret = asr_tls_connect(&ctx, AGENT_DOUBAO_ASR_HOST,
853	        AGENT_DOUBAO_ASR_PORT);
854	    if (ret != 0) {
855	        asr_tls_free(&ctx);
856	        return ret;
857	    }
858	
859	    /* 2. WebSocket upgrade */
860	    ret = ws_upgrade(&ctx, AGENT_DOUBAO_ASR_HOST,
861	        AGENT_DOUBAO_ASR_WS_PATH, token);
862	    if (ret != 0) {
