868	    ret = send_full_client_request(&ctx, app_id, token, cluster);
869	    if (ret != 0) {
870	        asr_tls_free(&ctx);
871	        return ret;
872	    }
873	
874	    /* 4. Stream audio chunks */
875	    size_t offset = 0;
876	    size_t chunk_size = AGENT_ASR_CHUNK_SIZE;
877	
878	    while (offset < pcm_len) {
879	        size_t remain = pcm_len - offset;
880	        size_t clen = (remain < chunk_size) ? remain : chunk_size;
881	        int is_last = (offset + clen >= pcm_len) ? 1 : 0;
882	
883	        ret = send_audio_chunk(&ctx, pcm_data + offset, clen,
884	            is_last);
885	        if (ret != 0) {
886	            syslog(LOG_ERR, "[%s] send_audio_chunk failed: %d\n",
887	                TAG, ret);
