893	
894	    syslog(LOG_INFO, "[%s] Sent %zu bytes in %zu-byte chunks\n",
895	        TAG, pcm_len, chunk_size);
896	
897	    /* 5. Receive responses until final (sequence < 0) */
898	    struct timespec asr_t0;
899	    clock_gettime(CLOCK_MONOTONIC, &asr_t0);
900	
901	    int attempts = 0;
902	    int max_attempts = 100; /* safety limit */
903	
904	    while (attempts < max_attempts) {
905	        ret = recv_volc_response(&ctx, text_out, text_cap);
906	        if (ret < 0) {
907	            syslog(LOG_ERR, "[%s] recv error: %d\n", TAG, ret);
908	            asr_tls_free(&ctx);
909	            return ret;
910	        }
911	        if (ret == 1) {
912	            break; /* final response received */
913	        }
914	        attempts++;
915	    }
916	
