492	static int send_volc_frame(asr_tls_ctx_t* ctx,
493	    unsigned char msg_type,
494	    unsigned char serialization,
495	    const unsigned char* payload,
496	    size_t plen)
497	{
498	    unsigned char* frame = malloc(VOLC_HDR_SIZE + plen);
499	
500	    if (!frame) {
501	        return -ENOMEM;
502	    }
503	
504	    frame[0] = VOLC_PROTO_VER;
505	    frame[1] = msg_type;
506	    frame[2] = serialization;
507	    frame[3] = 0x00;
508	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
509	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
510	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
511	    frame[7] = (unsigned char)(plen & 0xFF);
512	
513	    if (plen > 0) {
514	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
515	    }
516	
517	    int ret = ws_send_binary(ctx, frame, VOLC_HDR_SIZE + plen);
518	
519	    free(frame);
520	    return ret;
521	}
