547	    cJSON_AddNumberToObject(audio, "channel",
548	        AGENT_VOICE_CHANNELS);
549	
550	    /* request: bigmodel recognition */
551	    cJSON* req = cJSON_AddObjectToObject(root, "request");
552	
553	    cJSON_AddStringToObject(req, "model_name", "bigmodel");
554	    cJSON_AddBoolToObject(req, "enable_itn", 0);
555	    cJSON_AddBoolToObject(req, "enable_punc", 0);
556	    cJSON_AddBoolToObject(req, "show_utterances", 1);
