import socket, time, select
HOST="127.0.0.1"; PORT=5560; OUT="/tmp/vela_tight_out"
def connect_retry(t=60):
    end=time.time()+t
    while time.time()<end:
        try:
            s=socket.create_connection((HOST,PORT),timeout=5); s.setblocking(False); return s
        except OSError: time.sleep(1)
    return None
def drain(s,out,sec):
    end=time.time()+sec; buf=b""
    while time.time()<end:
        r,_,_=select.select([s],[],[],0.2)
        if r:
            try: d=s.recv(65536)
            except BlockingIOError: d=b""
            if not d: return buf
            buf+=d; out.write(d)
    return buf
def main():
