879	    long asr_ms = (asr_t1.tv_sec - asr_t0.tv_sec) * 1000
880	        + (asr_t1.tv_nsec - asr_t0.tv_nsec) / 1000000;
881	
882	    asr_tls_free(&ctx);
883	
884	    if (text_out[0] == '\0') {
885	        syslog(LOG_WARNING, "[%s] No text recognized (%ldms)\n",
886	            TAG, asr_ms);
887	        return -ENODATA;
888	    }
889	
890	    struct timespec e2e_t1;
891	    clock_gettime(CLOCK_MONOTONIC, &e2e_t1);
892	    long e2e_ms = (e2e_t1.tv_sec - e2e_t0.tv_sec) * 1000
893	        + (e2e_t1.tv_nsec - e2e_t0.tv_nsec) / 1000000;
894	
895	    syslog(LOG_INFO,
896	        "[%s] Recognized: %.80s (infer=%ldms e2e=%ldms)\n",
897	        TAG, text_out, asr_ms, e2e_ms);
898	    return 0;
899	}
