955	int volc_asr_stream_send(volc_asr_stream_t* s,
956	    const unsigned char* pcm, size_t len)
957	{
958	    if (!s || !s->ready || !pcm || len == 0) {
959	        return -EINVAL;
960	    }
961	
962	    int ret = send_audio_chunk(&s->tls, pcm, len, 0);
963	
964	    if (ret == 0) {
965	        /* Remember the tail so finish() can signal end-of-audio with a
966	         * NON-EMPTY last chunk.  The v3 bigmodel_async server treats an
967	         * empty AUDIO_LAST as an empty utterance; the working offline
968	         * path instead marks the last data chunk is_last=1, so mirror
969	         * that here. */
970	        size_t keep = (len < sizeof(s->last_chunk)) ? len
971	                                                    : sizeof(s->last_chunk);
972	
973	        memcpy(s->last_chunk, pcm + (len - keep), keep);
974	        s->last_len = keep;
975	    }
976	
977	    return ret;
978	}
979	
980	int volc_asr_stream_finish(volc_asr_stream_t* s,
981	    char* text_out, size_t text_cap)
982	{
983	    if (!s || !text_out || text_cap == 0) {
984	        free(s);
985	        return -EINVAL;
986	    }
987	
988	    text_out[0] = '\0';
989	
990	    if (!s->ready) {
991	        free(s);
992	        return -EINVAL;
993	    }
994	
995	    /* Signal end of audio with a NON-EMPTY last chunk: re-send the
996	     * remembered tail of the final audio chunk.  An empty AUDIO_LAST
997	     * makes the v3 bigmodel_async server finalize with no text. */
998	    static const unsigned char last_silence[2] = { 0, 0 };
999	    const unsigned char* tail = (s->last_len > 0)
1000	        ? s->last_chunk : last_silence;
1001	    size_t tail_len = (s->last_len > 0) ? s->last_len : 2;
1002	    int ret = send_audio_chunk(&s->tls, tail, tail_len, 1);
1003	
1004	    if (ret != 0) {
1005	        syslog(LOG_ERR, "[%s] stream: send last chunk failed: %d\n",
1006	            TAG, ret);
1007	        printf("DBG: stream send-last-chunk failed: %d\n", ret);
1008	        asr_tls_free(&s->tls);
1009	        free(s);
1010	        return ret;
1011	    }
1012	
1013	    /* Receive responses until final */
1014	    int attempts = 0;
1015	
1016	    while (attempts < 100) {
1017	        ret = recv_volc_response(&s->tls, text_out, text_cap);
1018	        if (ret < 0) {
1019	            syslog(LOG_ERR, "[%s] stream: recv error: %d\n",
1020	                TAG, ret);
1021	            printf("DBG: stream recv error: %d (attempt %d)\n",
1022	                ret, attempts);
1023	            asr_tls_free(&s->tls);
1024	            free(s);
1025	            return ret;
1026	        }
1027	        if (ret == 1) {
1028	            /* Final frame. The server's VAD may finalize leading
1029	             * silence as an empty utterance before the real speech
1030	             * arrives, so an empty final is NOT the end of the road:
1031	             * keep reading for a subsequent non-empty final. */
1032	            printf("DBG: stream final#%d: text='%.120s'\n",
1033	                attempts, text_out);
1034	            if (text_out[0] != '\0') {
1035	                break;
1036	            }
1037	        }
1038	        attempts++;
1039	    }
1040	    printf("DBG: stream recv done: %d attempts, text='%.120s'\n",
1041	        attempts, text_out);
1042	
1043	    asr_tls_free(&s->tls);
1044	    free(s);
1045	
1046	    if (text_out[0] == '\0') {
1047	        syslog(LOG_WARNING, "[%s] stream: no text recognized\n",
1048	            TAG);
1049	        return -ENODATA;
1050	    }
1051	
1052	    syslog(LOG_INFO, "[%s] stream: recognized: %.80s\n",
1053	        TAG, text_out);
1054	    return 0;
1055	}
