373	static void* recording_thread(void* arg)
374	{
375	    (void)arg;
376	    unsigned char chunk[AGENT_ASR_CHUNK_SIZE];
377	    int need_fallback = 0;
378	    int dump_fd = open("/data/cap_dump.pcm",
379	        O_WRONLY | O_CREAT | O_TRUNC, 0644);
380	    size_t total_bytes_read = 0;
381	    size_t total_bytes_sent = 0;
382	    int chunk_count = 0;
383	    int abnormal_exit = 0;
384	
385	    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n", TAG);
386	
387	    /* Use pre-connected ASR stream if available (opened in
388	     * voice_channel_start to avoid TLS handshake delay during
389	     * recording).  Fall back to opening a new session if not. */
390	    pthread_mutex_lock(&s_voice.lock);
391	    voice_asr_stream_t* stream = s_voice.asr_stream;
392	    s_voice.asr_stream = NULL; /* thread now owns it */
393	    pthread_mutex_unlock(&s_voice.lock);
394	
395	    if (!stream) {
396	        /* No pre-connected stream — open now (may lose first 300-800ms) */
397	        stream = voice_asr_stream_open();
398	        syslog(LOG_WARNING,
399	            "[%s] streaming ASR unavailable, batch fallback\n", TAG);
400	        need_fallback = 1;
401	
402	        pthread_mutex_lock(&s_voice.lock);
403	        if (alloc_fallback_buffer_locked() != 0) {
404	            s_voice.state = VOICE_IDLE;
405	            pthread_mutex_unlock(&s_voice.lock);
406	            sem_post(&s_voice.rec_ready);
407	            return NULL;
408	        }
409	        pthread_mutex_unlock(&s_voice.lock);
410	    } else {
411	        syslog(LOG_INFO, "[%s] using pre-connected ASR stream\n", TAG);
412	    }
413	
414	    /* Signal voice_channel_start() that we are ready to consume
415	     * audio frames. Without this, sem_wait in start() deadlocks. */
416	    sem_post(&s_voice.rec_ready);
417	
418	    /* No flush needed: the new start sequence guarantees that
419	     * audio_capture_start() runs AFTER this thread is ready,
420	     * so there is no stale data in the queue. The old flush
421	     * was harmful — audio_capture_read() blocks, so it would
422	     * consume real audio frames instead of stale ones. */
423	
424	    while (1) {
425	        pthread_mutex_lock(&s_voice.lock);
426	        enum voice_state st = s_voice.state;
427	        pthread_mutex_unlock(&s_voice.lock);
428	
429	        if (st != VOICE_RECORDING) {
430	            break;
431	        }
432	
433	        int n = audio_capture_read(s_voice.cap,
434	            chunk, sizeof(chunk));
435	
436	        if (n == -EAGAIN || n == -EWOULDBLOCK) {
437	            /* Non-blocking capture socket has no data yet (common right
438	             * after start before the first frames arrive). Retry instead
439	             * of treating it as a fatal error. */
440	            usleep(10000);
441	            continue;
442	        }
443	
444	        if (n <= 0) {
445	            syslog(LOG_WARNING,
446	                "[%s] capture read returned %d, stopping\n", TAG, n);
447	            abnormal_exit = 1;
448	            break;
449	        }
450	
451	        total_bytes_read += (size_t)n;
452	        chunk_count++;
453	
454	        /* Dump raw PCM to file */
455	        if (dump_fd >= 0) {
456	            write(dump_fd, chunk, (size_t)n);
457	        }
458	
459	        /* Log audio level for first few chunks and periodically
460	         * to diagnose silence vs actual speech from QEMU mic. */
461	        if (chunk_count <= 3 || chunk_count % 50 == 0) {
462	            int16_t* samples = (int16_t*)chunk;
463	            int sample_count = n / 2;
464	            int32_t peak = 0;
465	
466	            for (int i = 0; i < sample_count; i++) {
467	                int32_t v = samples[i] < 0 ? -samples[i] : samples[i];
468	                if (v > peak) {
469	                    peak = v;
470	                }
471	            }
472	            syslog(LOG_INFO,
473	                "[%s] chunk#%d: %d bytes, peak=%ld\n",
474	                TAG, chunk_count, n, (long)peak);
475	            printf("DBG: chunk#%d: %d bytes, peak=%ld\n",
476	                chunk_count, n, (long)peak);
477	        }
478	
479	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
480	        preproc_chunk(pp, chunk, n);
481	#endif
482	
483	        process_audio_chunk(&stream, chunk, (size_t)n,
484	            &need_fallback, &total_bytes_sent);
485	    }
486	
487	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
