491	    /* Store stream handle for voice_channel_stop to finish */
492	    if (dump_fd >= 0) {
493	        close(dump_fd);
494	        syslog(LOG_INFO, "[%s] PCM dump saved to /data/cap_dump.pcm\n", TAG);
