496	    }
497	
498	    pthread_mutex_lock(&s_voice.lock);
499	    s_voice.asr_stream = stream;
500	
501	    if (abnormal_exit && s_voice.state == VOICE_RECORDING) {
502	        syslog(LOG_WARNING, "[%s] abnormal exit, cleaning up\n", TAG);
503	        recording_cleanup_locked(stream);
504	    }
505	    pthread_mutex_unlock(&s_voice.lock);
506	
507	    syslog(LOG_INFO,
508	        "[%s] recording thread exit: %d chunks, %zu read, %zu sent%s\n",
509	        TAG, chunk_count, total_bytes_read, total_bytes_sent,
510	        abnormal_exit ? " (abnormal)" : "");
